-- Create indexes for better query performance
CREATE INDEX idx_mrna_gene_name ON mrna_sequences(gene_name);
CREATE INDEX idx_mrna_organism ON mrna_sequences(organism);
CREATE INDEX idx_plasmid_name ON plasmid_backbones(name);

-- Grant permissions
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO demo_user;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO demo_user;
